    bronze_glassannealingcart = { name = "Bronast voziček za ohlajanje stekla", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast voziček za ohlajanje stekla za steklarje." },
    silver_glassannealingcart = { name = "Srebrn voziček za ohlajanje stekla", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn voziček za ohlajanje stekla za steklarje." },
    gilded_glassannealingcart = { name = "Pozlačen voziček za ohlajanje stekla", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen voziček za ohlajanje stekla za steklarje." },
