    master_glassannealingcart_atelier = { name = "Mojstrski glassannealingcart atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glassannealingcart_palace = { name = "Suverena glassannealingcart palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassAnnealingCartMaker.ironStock=18; GlassAnnealingCartMaker.bronzeStock=14; GlassAnnealingCartMaker.woodStock=10; GlassAnnealingCartMaker.leatherStock=8; GlassAnnealingCartMaker.silverStock=8; GlassAnnealingCartMaker.goldStock=6; GlassAnnealingCartMaker.jewelStock=4; GlassAnnealingCartMaker.pearlStock=4
GlassAnnealingCartMaker.productStock = {}; GlassAnnealingCartMaker.buildings = {}; GlassAnnealingCartMaker.maker = nil; GlassAnnealingCartMaker.activeMaking = {}; GlassAnnealingCartMaker.totalProducts = 0; GlassAnnealingCartMaker.dayTimer = 0
function GlassAnnealingCartMaker.init() GlassAnnealingCartMaker.ironStock=18; GlassAnnealingCartMaker.bronzeStock=14; GlassAnnealingCartMaker.woodStock=10; GlassAnnealingCartMaker.leatherStock=8; GlassAnnealingCartMaker.silverStock=8; GlassAnnealingCartMaker.goldStock=6; GlassAnnealingCartMaker.jewelStock=4; GlassAnnealingCartMaker.pearlStock=4; GlassAnnealingCartMaker.productStock={}; GlassAnnealingCartMaker.buildings={}; GlassAnnealingCartMaker.maker=nil; GlassAnnealingCartMaker.activeMaking={}; GlassAnnealingCartMaker.totalProducts=0; GlassAnnealingCartMaker.dayTimer=0; print("[GlassAnnealingCartMaker] Royal Glass Annealing Cart Maker System initialized (6 products, 4 buildings)") end
function GlassAnnealingCartMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassAnnealingCartMaker.maker={name=n or ("Vozičkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vozičkar najet: %s (spretnost: %d)",GlassAnnealingCartMaker.maker.name,s),"success") end; return true end
function GlassAnnealingCartMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassAnnealingCartMaker.build(id) local ok,e=GlassAnnealingCartMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassAnnealingCartMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassAnnealingCartMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassAnnealingCartMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassAnnealingCartMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassAnnealingCartMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassAnnealingCartMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassAnnealingCartMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassAnnealingCartMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassAnnealingCartMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassAnnealingCartMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassAnnealingCartMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassAnnealingCartMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassAnnealingCartMaker.buildings==0 then return false,"Potrebna vozickarska delavnica" end; if not GlassAnnealingCartMaker.maker then return false,"Potreben vozickar" end; return true end
function GlassAnnealingCartMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassAnnealingCartMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassAnnealingCartMaker.ironStock=GlassAnnealingCartMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassAnnealingCartMaker.bronzeStock=GlassAnnealingCartMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassAnnealingCartMaker.woodStock=GlassAnnealingCartMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassAnnealingCartMaker.leatherStock=GlassAnnealingCartMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassAnnealingCartMaker.silverStock=GlassAnnealingCartMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassAnnealingCartMaker.goldStock=GlassAnnealingCartMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassAnnealingCartMaker.jewelStock=GlassAnnealingCartMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassAnnealingCartMaker.pearlStock=GlassAnnealingCartMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassAnnealingCartMaker.maker then t=math.max(1,t-math.floor(GlassAnnealingCartMaker.maker.skill/13)) end; table.insert(GlassAnnealingCartMaker.activeMaking,{id="glassannealingcart_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassAnnealingCartMaker.completeMaking(m) local q=1.0+(GlassAnnealingCartMaker.getQualityBonus()/100); if GlassAnnealingCartMaker.maker then q=q+(GlassAnnealingCartMaker.maker.skill/140) end; q=math.min(2.5,q); GlassAnnealingCartMaker.productStock[m.productType]=(GlassAnnealingCartMaker.productStock[m.productType] or 0)+m.quantity; GlassAnnealingCartMaker.totalProducts=GlassAnnealingCartMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassAnnealingCartMaker.maker then GlassAnnealingCartMaker.maker.itemsMade=GlassAnnealingCartMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassAnnealingCartMaker.maker.skill=math.min(100,GlassAnnealingCartMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Voziček izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassannealingcart.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassAnnealingCartMaker.update(dt) if not _G.state then return end; GlassAnnealingCartMaker.dayTimer=GlassAnnealingCartMaker.dayTimer+dt; if GlassAnnealingCartMaker.dayTimer>=30 then GlassAnnealingCartMaker.dayTimer=0; for i=#GlassAnnealingCartMaker.activeMaking,1,-1 do local m=GlassAnnealingCartMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassAnnealingCartMaker.completeMaking(m); table.remove(GlassAnnealingCartMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassAnnealingCartMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassAnnealingCartMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassAnnealingCartMaker.getStats() return {ironStock=GlassAnnealingCartMaker.ironStock,bronzeStock=GlassAnnealingCartMaker.bronzeStock,woodStock=GlassAnnealingCartMaker.woodStock,leatherStock=GlassAnnealingCartMaker.leatherStock,silverStock=GlassAnnealingCartMaker.silverStock,goldStock=GlassAnnealingCartMaker.goldStock,jewelStock=GlassAnnealingCartMaker.jewelStock,pearlStock=GlassAnnealingCartMaker.pearlStock,productStock=GlassAnnealingCartMaker.productStock,numBuildings=#GlassAnnealingCartMaker.buildings,hasMaker=GlassAnnealingCartMaker.maker~=nil,makerName=GlassAnnealingCartMaker.maker and GlassAnnealingCartMaker.maker.name or "—",makerSkill=GlassAnnealingCartMaker.maker and GlassAnnealingCartMaker.maker.skill or 0,activeMaking=#GlassAnnealingCartMaker.activeMaking,totalProducts=GlassAnnealingCartMaker.totalProducts} end
return GlassAnnealingCartMaker
